// run parses the arguments and dispatches: no arguments serves until ctx is
// cancelled or a termination signal arrives; "healthcheck" probes the serving
// process once and reports the verdict as its error; "version" prints the
// stamped release version. It is separated from main so the wiring is
// testable; main only handles the exit code.
func run(ctx context.Context, args []string, getenv func(string) string, stdout io.Writer) error {
	ctx, stop := signal.NotifyContext(ctx, os.Interrupt, syscall.SIGTERM)
	defer stop()

	switch {
	case len(args) == 0:
		return serve(ctx, getenv, stdout)
	case args[0] == connectNetworkName:
		// The one subcommand that takes flags, and the one that writes to
		// the database. Its own arguments are its own to check.
		return connectNetworkCommand(ctx, args[1:], getenv, stdout)
	case args[0] == seedName:
		// Local development only, and it refuses anything but the fixture
		// adapter itself - see seedInputs for why that is a refusal rather
		// than a warning. Its own arguments are its own to check.
		return seedCommand(ctx, args[1:], getenv, stdout)
	case args[0] == publishOfferName:
		// The other subcommand that writes to the database: one rate band
		// on one route of the configured network (#537). Its own arguments
		// are its own to check.
		return publishOfferCommand(ctx, args[1:], getenv, stdout)
	case args[0] == importCatalogueName:
		// The scheduled catalogue import, run once by hand under the same
		// lock, for the operator who has just connected a network and
		// should not be waiting on a timer.
		return importCatalogueCommand(ctx, args[1:], getenv, stdout)
	case args[0] != "healthcheck" && args[0] != "version":
		return fmt.Errorf("unknown command %q", args[0])
	case len(args) > 1:
		return fmt.Errorf("%s takes no arguments, got %q", args[0], args[1:])
	case args[0] == "version":
		_, err := fmt.Fprintf(stdout, "apivo version %s\n", version)
		return err
	default:
		return healthcheck(ctx, getenv)
	}
}

